<?php

namespace App\Domain\Export;

/**
 * A16 / A48: checkins.csv. A user-controlled cell that starts with =, +, -, @, tab or carriage
 * return gets a leading single quote (a spreadsheet would read it as a formula); then RFC 4180
 * quoting. Rows end with LF.
 */
final class CsvWriter
{
    public const array HEADER = ['local_date', 'habit_id', 'habit_name', 'category', 'type', 'value', 'unit', 'target', 'completed', 'note'];

    /** The cells a person typed; every other cell is generated by the server. */
    public const array USER_CELLS = ['habit_name', 'unit', 'note'];

    private const array FORMULA_STARTS = ['=', '+', '-', '@', "\t", "\r"];

    public static function neutralise(string $cell): string
    {
        return $cell !== '' && in_array($cell[0], self::FORMULA_STARTS, true) ? "'".$cell : $cell;
    }

    public static function quote(string $cell): string
    {
        return strpbrk($cell, ",\"\r\n") === false ? $cell : '"'.str_replace('"', '""', $cell).'"';
    }

    /** One user-controlled cell, neutralised then quoted. */
    public static function userCell(?string $cell): string
    {
        return self::quote(self::neutralise($cell ?? ''));
    }

    /** @param array<string, string|bool|null> $row keyed by HEADER */
    public static function row(array $row): string
    {
        $cells = [];
        foreach (self::HEADER as $column) {
            $value = $row[$column] ?? null;
            $text = is_bool($value) ? ($value ? 'true' : 'false') : (string) ($value ?? '');
            $cells[] = in_array($column, self::USER_CELLS, true) ? self::userCell($text) : self::quote($text);
        }

        return implode(',', $cells)."\n";
    }

    public static function header(): string
    {
        return implode(',', self::HEADER)."\n";
    }
}
